    SELECT 'zonas-subestepicas-de-6220', '6220', 'Zonas subestépicas de gramíneas y anuales del Thero-Brachypodietea', 'Pastos', 'Pastizales secos en los que conviven gramíneas vivaces de mata dura, como el lastón (Brachypodium retusum) o el esparto, con una multitud de plantas anuales diminutas que nacen con las lluvias y se secan antes del verano. En agosto parecen un erial pardo; en abril pueden reunir cuarenta especies distintas en un metro cuadrado. Esa riqueza escondida es la razón de que sea un hábitat prioritario.', 1, 37.897375, -1.402041, '#66cdaa', '{"type":"MultiPolygon","coordinates":[[[[-1.452688,37.88058],[-1.452676,37.880559],[-1.452659,37.880533],[-1.452638,37.880508],[-1.452615,37.880485],[-1.452589,37.880464],[-1.452561,37.880444],[-1.452531,37.880426],[-1.4525,37.880411],[-1.452466,37.880397],[-1.452431,37.880386],[-1.452396,37.880377],[-1.452356,37.880365],[-1.452318,37.880351],[-1.45228,37.880335],[-1.452244,37.880317],[-1.45221,37.880297],[-1.452177,37.880275],[-1.452147,37.880252],[-1.452118,37.880227],[-1.452092,37.8802],[-1.452069,37.880174],[-1.452061,37.880162],[-1.452049,37.880138],[-1.452037,37.880113],[-1.452025,37.880089],[-1.452014,37.880064],[-1.452002,37.880039],[-1.451992,37.880015],[-1.45197,37.879965],[-1.45196,37.87994],[-1.451958,37.879934],[-1.451941,37.879891],[-1.451933,37.87987],[-1.451923,37.879851],[-1.451912,37.879833],[-1.451899,37.879816],[-1.451884,37.8798],[-1.451868,37.879785],[-1.45185,37.879771],[-1.451831,37.879758],[-1.451811,37.879746],[-1.45179,37.879735],[-1.451764,37.879724],[-1.451381,37.879544],[-1.450922,37.879345],[-1.450866,37.879323],[-1.450809,37.8793],[-1.450753,37.879277],[-1.450696,37.879254],[-1.450639,37.87923],[-1.450583,37.879207],[-1.450526,37.879183],[-1.45047,37.879159],[-1.450414,37.879135],[-1.450358,37.879112],[-1.450302,37.879088],[-1.450298,37.879086],[-1.45027,37.879072],[-1.450322,37.879154],[-1.450395,37.879245],[-1.450453,37.879339],[-1.450554,37.879441],[-1.450656,37.879533],[-1.4