    SELECT 'Pino carrasco', 'Pinus halepensis', 'flora', 'Conífera', 'Laderas secas y soleadas sobre calizas y margas, en clima mediterráneo cálido', 'Pino de copa clara e irregular y follaje de un verde pálido, el más resistente a la sequía y a los suelos pobres de los pinos ibéricos. Sus piñas, alargadas y asimétricas, quedan colgadas años en la rama y liberan las semillas tras los incendios, lo que le permite recolonizar rápido.', NULL, 'Copa irregular y poco densa, de verde claro; Piñas asimétricas y persistentes, apuntando hacia atrás; Corteza clara y agrietada, rojiza en las ramas jóvenes', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Pino_secolare_-_Castelleone_di_Suasa.JPG?width=1280', 'Accurimbono (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 2 ocurrencias dentro de los polígonos de hábitat del espacio (2 hábitats; barrido de 2026-08-22); Atlas y Manual de los Hábitats de España (MITECO, 2005): especie característica de alguno de los HIC cartografiados aquí; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Pinopsida', 'Pinales', 'Pinaceae', 'Pinus', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2013)', NULL, 'No catalogada (especie forestal común)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 7118, 5285604, 2, NULL, NULL, NULL
    UNION ALL
    SELECT 'Cinomorio', 'Cynomorium coccineum', 'flora', 'Planta parásita', 'Saladares y matorrales halonitrófilos', 'Planta parásita sin clorofila, de aspecto de maza rojiza, que crece sobre las raíces de quenopodiáceas halófilas de los saladares y estepas salinas.', NULL, 'Inflorescencia carnosa rojo-oscura en maza; Sin hojas verdes (parásita); Aparece sobre raíces de plantas halófilas', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Cynomorium_coccineum_vMH375.jpg?width=1280', 'autor no indicado (Public domain) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)","ambito":"autonómico","origen":"regionalStatus del park.json"}', 0, 1, NULL, 'GBIF: 1 ocurrencia dentro de los polígonos de hábitat del espacio (2 hábitats; barrido de 2026-08-22); EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Tracheophyta', 'Magnoliopsida', 'Saxifragales', 'Cynomoriaceae', 'Cynomorium', 'No evaluada en la Lista Roja mundial de la UICN', NULL, 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)', 'Región de Murcia', NULL, 3790, 7445043, 1, NULL, NULL, NULL
