    SELECT 'Cerrillo', 'Hyparrhenia hirta', 'flora', 'Gramínea', 'Laderas secas, ribazos y pastizales sobre suelos pedregosos', 'Gramínea perenne que forma matas y espiga en verano, cuando el resto del pastizal ya está agostado. Sus espiguillas van por parejas, cubiertas de pelos rojizos y con aristas retorcidas. Da al paisaje un tono dorado rojizo a final de verano.', NULL, 'Espiguillas peludas agrupadas por parejas; Aristas retorcidas y acodadas; Espiga en verano, cuando lo demás está seco', 'Verano y otoño', 'https://commons.wikimedia.org/wiki/Special:FilePath/Hyparrhenia_hirta_Habitus_ValledeAlcudia.jpg?width=1280', 'Javier martin (Public domain) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 1 ocurrencia dentro de los polígonos de hábitat del espacio (2 hábitats; barrido de 2026-08-22); Atlas y Manual de los Hábitats de España (MITECO, 2005): especie característica de alguno de los HIC cartografiados aquí; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Liliopsida', 'Poales', 'Poaceae', 'Hyparrhenia', 'No evaluada en la Lista Roja mundial de la UICN', NULL, 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 10047, 2703243, 1, NULL, NULL, NULL
    UNION ALL
    SELECT 'Siempreviva insigne', 'Limonium insigne', 'flora', 'Hierba', 'Suelos margosos y yesosos salinos, en estepas y taludes áridos', 'Una de las siemprevivas más vistosas: sus inflorescencias forman un ramillete denso de un lila rosado intenso que destaca sobre el gris de las margas. Es un endemismo del sureste ibérico, ligado a suelos salinos y yesosos, y muy usado en seco como flor ornamental.', NULL, 'Floración densa y de lila rosado vivo, muy llamativa; Hojas en roseta basal, gruesas y de borde ondulado; Sobre margas y yesos claros, en terreno casi desnudo', 'Final de primavera y verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/Limonium_insigne.jpg?width=1280', 'ANE (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)","ambito":"autonómico","origen":"regionalStatus del park.json"}', 0, 1, NULL, 'GBIF: 1 ocurrencia dentro de los polígonos de hábitat del espacio (2 hábitats; barrido de 2026-08-22); EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Tracheophyta', 'Magnoliopsida', 'Caryophyllales', 'Plumbaginaceae', 'Limonium', 'No evaluada en la Lista Roja mundial de la UICN', NULL, 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)', 'Región de Murcia', NULL, 5836, 4088635, 1, NULL, NULL, NULL
    UNION ALL
    SELECT 'Albardín', 'Lygeum spartum', 'flora', 'Gramínea', 'Estepas salinas, margas y suelos yesosos secos; forma albardinales', 'Gramínea perenne de hojas duras y punzantes que forma matas separadas sobre suelos salinos y margosos donde poco más prospera. Su inflorescencia es inconfundible: una espata blanca y sedosa que envuelve las flores como un capuchón de papel.', NULL, 'Espata blanca y sedosa envolviendo la espiga; Hojas rígidas terminadas en punta punzante; Matas espaciadas sobre suelo desnudo y claro', 'Todo el año (espigado en primavera)', 'https://commons.wikimedia.org/wiki/Special:FilePath/Lygeum_spartum-1.jpg?width=1280', 'Nanosanchez (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 1 ocurrencia dentro de los polígonos de hábitat del espacio (2 hábitats; barrido de 2026-08-22); Atlas y Manual de los Hábitats de España (MITECO, 2005): especie característica de alguno de los HIC cartografiados aquí; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Liliopsida', 'Poales', 'Poaceae', 'Lygeum', 'LC', NULL, 'No catalogada en la Lista Roja de la Flora Vascular Española 2008', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 10060, 2704651, 1, NULL, NULL, NULL
    UNION ALL
    SELECT 'Culebra bastarda', 'Malpolon monspessulanus', 'fauna', 'Reptil', 'Matorral litoral y laderas secas', 'La culebra más grande de la península, de hasta dos metros y medio, con un aspecto inconfundible: ojos grandes de pupila redonda bajo unas escamas salientes que le dan «cejas» y expresión de enfado. Es diurna, muy rápida y venenosa, pero con los colmillos al fondo de la boca, por lo que no supone riesgo si no se la manipula.', NULL, 'Escamas prominentes sobre los ojos, como cejas; Ojo grande con pupila redonda y iris amarillento; Adultos de dorso pardo oliváceo uniforme; jóvenes muy manchados', 'Primavera a otoño', 'https://commons.wikimedia.org/wiki/Special:FilePath/Culebra_bastarda_(Malpolon_monspessulanus)%2C_Nig%C3%BCella%2C_Zaragoza%2C_Espa%C3%B1a%2C_2017-05-24%2C_DD_07.jpg?width=1280', 'Diego Delso (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 1 ocurrencia dentro de los polígonos de hábitat del espacio (2 hábitats; barrido de 2026-08-22); Decreto n.º 13/1995, de 31 de marzo, PORN de Sierra Espuña (incluido Barrancos de Gebas), artículos 13, 14 y 16 (BORM n.º 85, de 11 de abril de 1995): la norma la enumera en el ámbito ENTERO del PORN, 19.679 ha, del que el Paisaje Protegido de los Barrancos de Gebas son 1.875 (9,5 %) y el resto el Parque Regional de Sierra Espuña y su periferia. El artículo 16.1.a dice literalmente «aquellas presentes en el ámbito del Plan», y el Plan NO reparte las especies entre los dos espacios: solo separa los hábitats, en su artículo 17; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Chordata', 'Reptilia', 'Squamata', 'Lamprophiidae', 'Malpolon', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2009)', 'LC — Preocupación menor (Lista Roja española, 2002)', 'LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 11772, 8796529, 1, NULL, NULL, NULL
    UNION ALL
    SELECT 'Galápago leproso', 'Mauremys leprosa', 'fauna', 'Reptil', 'Ríos, charcas, balsas y tramos remansados con vegetación y soleaderos', 'Galápago de agua con el caparazón aplanado y de color verde oliva a pardo, a menudo cubierto de algas. Los ejemplares jóvenes muestran manchas anaranjadas en el cuello y en los lados de la cabeza que se van apagando con la edad. Toma el sol sobre piedras y troncos y se lanza al agua al menor ruido.', NULL, 'Manchas anaranjadas en el cuello, más vivas de joven; Caparazón bajo y aplanado, a menudo con algas; Se tira al agua en cuanto detecta movimiento en la orilla', 'Primavera a otoño (inactivo en invierno)', 'https://commons.wikimedia.org/wiki/Special:FilePath/Mauremys_leprosa_03_by-dpc.jpg?width=1280', 'David Perez (CC BY 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 1 ocurrencia dentro de los polígonos de hábitat del espacio (2 hábitats; barrido de 2026-08-22); EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Reptilia', 'Testudines', 'Geoemydidae', 'Mauremys', 'No evaluada en la Lista Roja mundial de la UICN', 'VU — Vulnerable (Lista Roja española, 2002)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero) · Anexo II (Ley 42/2007, de 13 de diciembre) · Anexo V (Ley 42/2007, de 13 de diciembre)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 11585, 2443341, 1, NULL, NULL, NULL
    UNION ALL
    SELECT 'Ononis ornithopodioides', 'Ononis ornithopodioides', 'flora', 'Hierba', 'Pastizales anuales y claros de matorral sobre suelos secos', 'Pequeña leguminosa anual de tallos finos y glandulosos, con hojas de tres foliolos y flores amarillas diminutas. Sus legumbres, curvadas y dispuestas en grupo, recuerdan a los dedos de una pata de pájaro, lo que le da el nombre científico.', NULL, 'Legumbres curvas agrupadas, como una pata de ave; Flores amarillas muy pequeñas; Tallos pegajosos al tacto, con pelos glandulosos', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Ononis_ornithopodioides_kz1.jpg?width=1280', 'Krzysztof Ziarnek, Kenraiz (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 1 ocurrencia dentro de los polígonos de hábitat del espacio (2 hábitats; barrido de 2026-08-22); Atlas y Manual de los Hábitats de España (MITECO, 2005): especie característica de alguno de los HIC cartografiados aquí; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Fabales', 'Fabaceae', 'Ononis', 'No evaluada en la Lista Roja mundial de la UICN', NULL, 'Sin figura de protección nacional específica registrada en EIDOS', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 6696, 2977204, 1, NULL, NULL, NULL
    UNION ALL
    SELECT 'Lentisco', 'Pistacia lentiscus', 'flora', 'Arbusto', 'Matorral mediterráneo litoral', 'Arbusto perennifolio de hojas compuestas sin foliolo terminal y con el raquis alado, un detalle que lo separa de la cornicabra. Al frotarlo huele intensamente a resina. Sus frutos, en racimo, pasan de rojo a negro y son alimento clave para aves en otoño.', NULL, 'Hoja compuesta con número par de foliolos, sin uno terminal; Raquis de la hoja con dos alas laterales; Olor fuerte a resina al frotar las hojas', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Pistacia_lentiscus.jpg?width=1280', 'Lumbar~commonswiki (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 1 ocurrencia dentro de los polígonos de hábitat del espacio (2 hábitats; barrido de 2026-08-22); Decreto n.º 13/1995, de 31 de marzo, PORN de Sierra Espuña (incluido Barrancos de Gebas), artículos 13, 14 y 16 (BORM n.º 85, de 11 de abril de 1995): la norma la enumera en el ámbito ENTERO del PORN, 19.679 ha, del que el Paisaje Protegido de los Barrancos de Gebas son 1.875 (9,5 %) y el resto el Parque Regional de Sierra Espuña y su periferia. El artículo 16.1.a dice literalmente «aquellas presentes en el ámbito del Plan», y el Plan NO reparte las especies entre los dos espacios: solo separa los hábitats, en su artículo 17, que la cita como «Pistacea lentiscus» (errata de imprenta del género: la norma escribe «Pistacea»); EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Sapindales', 'Anacardiaceae', 'Pistacia', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2016)', NULL, 'No catalogada (especie común mediterránea)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 7129, 3190583, 1, NULL, NULL, NULL
    UNION ALL
    SELECT 'Lagartija colilarga', 'Psammodromus algirus', 'fauna', 'Reptil', 'Matorral litoral y laderas secas', 'Lagartija esbelta de escamas grandes, quilladas y brillantes, con dos líneas claras muy marcadas a cada lado del dorso. La cola puede medir el doble que el cuerpo. Los machos lucen en primavera manchas azules en el hombro y las mejillas anaranjadas.', NULL, 'Dos líneas claras nítidas a lo largo de cada costado; Escamas grandes y quilladas, de aspecto brillante; Cola larguísima, hasta el doble que el cuerpo', 'Primavera a otoño', 'https://commons.wikimedia.org/wiki/Special:FilePath/Psammodromus_algirus_-_01.jpg?width=1280', 'Carlos Delgado (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 1 ocurrencia dentro de los polígonos de hábitat del espacio (2 hábitats; barrido de 2026-08-22); Decreto n.º 13/1995, de 31 de marzo, PORN de Sierra Espuña (incluido Barrancos de Gebas), artículos 13, 14 y 16 (BORM n.º 85, de 11 de abril de 1995): la norma la enumera en el ámbito ENTERO del PORN, 19.679 ha, del que el Paisaje Protegido de los Barrancos de Gebas son 1.875 (9,5 %) y el resto el Parque Regional de Sierra Espuña y su periferia. El artículo 16.1.a dice literalmente «aquellas presentes en el ámbito del Plan», y el Plan NO reparte las especies entre los dos espacios: solo separa los hábitats, en su artículo 17; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Reptilia', 'Squamata', 'Lacertidae', 'Psammodromus', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2009)', 'LC — Preocupación menor (Lista Roja española, 2002)', 'LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 10670, 2469763, 1, NULL, NULL, NULL
    UNION ALL
    SELECT 'Espino negro', 'Rhamnus lycioides', 'flora', 'Arbusto', NULL, 'Es un arbustillo de hasta 3 m de altura (López González, 2001), que frecuentemente tiene aspecto de mata alta o media, más o menos espinoso, de ramificación intricada y de perennifolio a semicaducifolio facultativo. Sus especímenes tienen espinas pero presentan una variabilidad: los de las regiones continentales y mediterráneas más áridas las llegan a tener en cantidad y longitud exagerada, pero otros son casi inermes. Presenta también unas ramillas laterales cortas terminadas en un fascículo de hojas. Éstas se disponen alternas, aunque a veces algunas se muestran casi opuestas; son simples, sin peciolo y con un limbo estrecho (tíìcamente menor de 0,5 cm), a veces muy corto, menor de 1,2 cm (subsp. borgiae), de trasovado-oblongo a espatulado-linear, lampiño o con un pelillo muy corto (subesp. velutina).', NULL, NULL, 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Rhamnus_lycioides_fruits.JPG?width=1280', 'איתן פרמן (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 1 ocurrencia dentro de los polígonos de hábitat del espacio (2 hábitats; barrido de 2026-08-22); Decreto n.º 13/1995, de 31 de marzo, PORN de Sierra Espuña (incluido Barrancos de Gebas), artículos 13, 14 y 16 (BORM n.º 85, de 11 de abril de 1995): la norma la enumera en el ámbito ENTERO del PORN, 19.679 ha, del que el Paisaje Protegido de los Barrancos de Gebas son 1.875 (9,5 %) y el resto el Parque Regional de Sierra Espuña y su periferia. El artículo 16.1.a dice literalmente «aquellas presentes en el ámbito del Plan», y el Plan NO reparte las especies entre los dos espacios: solo separa los hábitats, en su artículo 17; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Rosales', 'Rhamnaceae', 'Rhamnus', 'No evaluada en la Lista Roja mundial de la UICN', NULL, 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia ni en Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de la Región de Murcia ni en Catalogación de la malvasía cabeciblanca (Región de Murcia)', 'Región de Murcia', NULL, 7730, 6371380, 1, NULL, NULL, NULL
    UNION ALL
    SELECT 'Curruca cabecinegra', 'Curruca melanocephala', 'fauna', 'Ave', 'Matorral mediterráneo denso, setos y bordes de arbolado', 'La curruca más común del matorral mediterráneo. El macho tiene la cabeza negra hasta por debajo del ojo, la garganta blanca y un llamativo anillo ocular rojo. Es ruidosa y territorial: su reclamo de alarma es un traqueteo seco que delata su presencia constantemente.', NULL, 'Capucha negra que baja por debajo del ojo; Anillo ocular rojo intenso; Reclamo de alarma como una carraca seca', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Sardinian_Warbler.jpg?width=1280', 'Andreas Trepte (CC BY-SA 2.5) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE (RD 139/2011)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE (RD 139/2011)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF confirma su presencia con 122 ocurrencias dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Decreto n.º 13/1995, de 31 de marzo, PORN de Sierra Espuña (incluido Barrancos de Gebas), artículos 13, 14 y 16 (BORM n.º 85, de 11 de abril de 1995): la norma la enumera en el ámbito ENTERO del PORN, 19.679 ha, del que el Paisaje Protegido de los Barrancos de Gebas son 1.875 (9,5 %) y el resto el Parque Regional de Sierra Espuña y su periferia. El artículo 16.1.a dice literalmente «aquellas presentes en el ámbito del Plan», y el Plan NO reparte las especies entre los dos espacios: solo separa los hábitats, en su artículo 17, que la cita como «Sylvia melanocephala»; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Passeriformes', 'Sylviidae', 'Curruca', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2018)', 'DD — Datos insuficientes (Lista Roja española, 2004)', 'LESRPE (RD 139/2011)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 80929, 9990095, 122, NULL, NULL, NULL
    UNION ALL
    SELECT 'Cogujada montesina', 'Galerida theklae', 'fauna', 'Ave', 'Matorral bajo, laderas pedregosas y eriales con vegetación rala', 'Cogujada de cresta puntiaguda, muy parecida a la común pero de pico más corto y grueso y con el pecho más nítidamente rayado. Prefiere el matorral y las laderas pedregosas, mientras que la común busca cultivos, caminos y bordes de pueblo.', NULL, 'Cresta alta y afilada, casi triangular; Pico más corto y romo que el de la cogujada común; Rayado del pecho bien definido, no difuminado', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Galerida_theklae_Madrid.jpg?width=1280', 'Adrian198cm (Public domain) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF confirma su presencia con 73 ocurrencias dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Decreto n.º 13/1995, de 31 de marzo, PORN de Sierra Espuña (incluido Barrancos de Gebas), artículos 13, 14 y 16 (BORM n.º 85, de 11 de abril de 1995): la norma la enumera en el ámbito ENTERO del PORN, 19.679 ha, del que el Paisaje Protegido de los Barrancos de Gebas son 1.875 (9,5 %) y el resto el Parque Regional de Sierra Espuña y su periferia. El artículo 16.1.a dice literalmente «aquellas presentes en el ámbito del Plan», y el Plan NO reparte las especies entre los dos espacios: solo separa los hábitats, en su artículo 17; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Passeriformes', 'Alaudidae', 'Galerida', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2017)', 'NE — No evaluada (Lista Roja española, 2004)', 'LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial); Directiva Aves 2009/147/CE, Anexo I', 'No incluida en Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia ni en Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de la Región de Murcia ni en Catalogación de la malvasía cabeciblanca (Región de Murcia)', 'Región de Murcia', NULL, 12316, 9330514, 73, NULL, NULL, NULL
    UNION ALL
    SELECT 'Cernícalo vulgar', 'Falco tinnunculus', 'fauna', 'Ave rapaz', 'Campos abiertos, matorral, cortados y también ciudades', 'El halcón más común y fácil de ver, gracias a su costumbre de cernirse: se queda suspendido en el aire batiendo las alas con la cabeza inmóvil, buscando ratones y lagartijas. El macho tiene la cabeza gris y el dorso rojizo con puntos negros; la hembra es más parda y barrada.', NULL, 'Se queda «clavado» en el aire cerniéndose; Dorso rojizo salpicado de puntos negros; Cola larga con una banda negra ancha en la punta', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Common_kestrel_falco_tinnunculus.jpg?width=1280', 'Andreas Trepte (CC BY-SA 2.5) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"Directiva Aves 2009/147/CE (Red Natura 2000)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"Directiva Aves 2009/147/CE (Red Natura 2000)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF confirma su presencia con 61 ocurrencias dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Decreto n.º 13/1995, de 31 de marzo, PORN de Sierra Espuña (incluido Barrancos de Gebas), artículos 13, 14 y 16 (BORM n.º 85, de 11 de abril de 1995): la norma la enumera en el ámbito ENTERO del PORN, 19.679 ha, del que el Paisaje Protegido de los Barrancos de Gebas son 1.875 (9,5 %) y el resto el Parque Regional de Sierra Espuña y su periferia. El artículo 16.1.a dice literalmente «aquellas presentes en el ámbito del Plan», y el Plan NO reparte las especies entre los dos espacios: solo separa los hábitats, en su artículo 17; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Falconiformes', 'Falconidae', 'Falco', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2021)', 'NE — No evaluada (Lista Roja española, 2004)', 'Directiva Aves 2009/147/CE (Red Natura 2000)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 12321, 9616058, 61, NULL, NULL, NULL
    UNION ALL
    SELECT 'Gorrión chillón', 'Petronia petronia', 'fauna', 'Ave', NULL, 'El chillón es un gorrión grande y corpulento, con la cabeza robusta y el pico muy fuerte. En su plumaje dominan los tonos marróngrisáceos con un profuso listado oscuro en el dorso. Las partes inferiores, por el contrario, son claras y están adornadas con amplias listas de color gris parduzco. En la cabeza destacan tres listas anchas: una clara; otra marrón-grisácea tras el ojo bajo aquella, y, por encima, una parda oscura. Otra lista de color marrón pálido recorre el píleo. Bajo la garganta presenta una mancha amarilla que a menudo permanece oculta o poco visible. En la cola aparecen unas manchas blancas hacia los extremos, que resultan bien visibles en vuelo. No hay diferencias de coloración entre machos y hembras. Los jóvenes son difíciles de distinguir de los adultos, incluso recién volados del nido. Se diferencian de estos por carecer de la mancha amarilla en la garganta. Asimismo, el dibujo de la cara presenta en ellos un aspecto poco definido y su coloración general es más suave.', NULL, NULL, 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Petronia_petronia_-Ariege%2C_Midi-Pyrenee%2C_France-8-4c.jpg?width=1280', 'Petronia_petronia_-Ariege,_Midi-Pyrenee,_France-8.jpg: Sandra from … (CC BY 2.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF confirma su presencia con 61 ocurrencias dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Decreto n.º 13/1995, de 31 de marzo, PORN de Sierra Espuña (incluido Barrancos de Gebas), artículos 13, 14 y 16 (BORM n.º 85, de 11 de abril de 1995): la norma la enumera en el ámbito ENTERO del PORN, 19.679 ha, del que el Paisaje Protegido de los Barrancos de Gebas son 1.875 (9,5 %) y el resto el Parque Regional de Sierra Espuña y su periferia. El artículo 16.1.a dice literalmente «aquellas presentes en el ámbito del Plan», y el Plan NO reparte las especies entre los dos espacios: solo separa los hábitats, en su artículo 17; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Passeriformes', 'Passeridae', 'Petronia', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2016)', 'NE — No evaluada (Lista Roja española, 2004)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 11973, 2492350, 61, NULL, NULL, NULL
    UNION ALL
    SELECT 'Pimientera', 'Fringilla coelebs', 'fauna', 'Ave', 'Bosques, arboledas, huertos y jardines con arbolado', 'Uno de los pájaros más abundantes de Europa. El macho luce el pecho vinoso y la nuca gris azulada; la hembra es parda. Ambos comparten dos barras alares blancas muy visibles en vuelo. Su canto es una frase descendente que acaba en un floreo, repetida sin descanso en primavera.', NULL, 'Dos barras blancas bien marcadas en cada ala; Bordes blancos en la cola, visibles al volar; Canto en frase descendente que remata en un adorno', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Fringilla_coelebs_(chaffinch)%2C_male.jpg?width=1280', 'Self: Commons user MichaelMaggs (CC BY-SA 2.5) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF confirma su presencia con 60 ocurrencias dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Decreto n.º 13/1995, de 31 de marzo, PORN de Sierra Espuña (incluido Barrancos de Gebas), artículos 13, 14 y 16 (BORM n.º 85, de 11 de abril de 1995): la norma la enumera en el ámbito ENTERO del PORN, 19.679 ha, del que el Paisaje Protegido de los Barrancos de Gebas son 1.875 (9,5 %) y el resto el Parque Regional de Sierra Espuña y su periferia. El artículo 16.1.a dice literalmente «aquellas presentes en el ámbito del Plan», y el Plan NO reparte las especies entre los dos espacios: solo separa los hábitats, en su artículo 17; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Passeriformes', 'Fringillidae', 'Fringilla', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2019)', 'NE — No evaluada (Lista Roja española, 2004)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 11047, 2494422, 60, NULL, NULL, NULL
    UNION ALL
    SELECT 'Pito ibérico', 'Picus sharpei', 'fauna', 'Ave', NULL, 'Es un pájaro carpintero grande y robusto, de aspecto inconfundible, en cuyo plumaje dominan claramente los tonos verdosos, más intensos en las regiones dorsales, ligeramente grisáceos en las ventrales y con matices amarillentos en el obispillo. Carece de moteados y listas —salvo, tenuemente, en la región anal—, pero luce un llamativo patrón de coloración en la cabeza, donde el píleo es rojo y los ojos, amarillentos, aparecen enmarcados por un antifaz negro. Los machos y los jóvenes presentan una bigotera negra y roja, que es exclusivamente negra en las hembras. El plumaje juvenil se caracteriza por ser fuertemente moteado, especialmente en las partes inferiores, aunque, en conjunto, su coloración es más apagada que la del adulto, no presentan antifaz y poseen un iris más oscuro. Su vuelo es muy característico, con una trayectoria ondulatoria en la que el ave combina tramos en los que bate las alas con otros en que las pliega.', NULL, NULL, 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Iberian_Green_Woodpecker_(Pito_Ib%C3%A9rico)_(Picus_sharpei)_-_Torrevieja%2C_Spain_2024-02-04.jpg?width=1280', 'Ryan Hodnett (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF confirma su presencia con 60 ocurrencias dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Decreto n.º 13/1995, de 31 de marzo, PORN de Sierra Espuña (incluido Barrancos de Gebas), artículos 13, 14 y 16 (BORM n.º 85, de 11 de abril de 1995): la norma la enumera en el ámbito ENTERO del PORN, 19.679 ha, del que el Paisaje Protegido de los Barrancos de Gebas son 1.875 (9,5 %) y el resto el Parque Regional de Sierra Espuña y su periferia. El artículo 16.1.a dice literalmente «aquellas presentes en el ámbito del Plan», y el Plan NO reparte las especies entre los dos espacios: solo separa los hábitats, en su artículo 17, que la cita como «Picus viridis»; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Piciformes', 'Picidae', 'Picus', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2020)', 'NE — No evaluada (Lista Roja española, 2004)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 33014, 9029556, 60, NULL, NULL, NULL
    UNION ALL
    SELECT 'Chova piquirroja', 'Pyrrhocorax pyrrhocorax', 'fauna', 'Ave', 'Cortados rocosos, cantiles y montañas, alimentándose en pastizales cercanos', 'Córvido negro y brillante con el pico rojo, largo y curvo, y las patas del mismo color encendido. Vuela en grupos acrobáticos junto a los cantiles, plegando las alas y dejándose caer por puro juego. Busca larvas hurgando en el suelo de los pastos con ese pico de sonda.', NULL, 'Pico rojo, largo y curvado hacia abajo; Reclamo agudo, un «chiaa» nasal muy característico; Plumas de la punta del ala muy separadas, como dedos', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Pyrrhocorax_pyrrhocorax_-standing-8.jpg?width=1280', 'File:Alpenkrähe.jpg: "Malte Uhl (User:Zzzip)" derivative work: Snow… (CC BY-SA 2.5) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE (RD 139/2011)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de Murcia (Ley 7/1995): De interés especial","ambito":"autonómico","origen":"regionalStatus del park.json"}', 0, 1, NULL, 'GBIF confirma su presencia con 60 ocurrencias dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Decreto n.º 13/1995, de 31 de marzo, PORN de Sierra Espuña (incluido Barrancos de Gebas), artículos 13, 14 y 16 (BORM n.º 85, de 11 de abril de 1995): la norma la enumera en el ámbito ENTERO del PORN, 19.679 ha, del que el Paisaje Protegido de los Barrancos de Gebas son 1.875 (9,5 %) y el resto el Parque Regional de Sierra Espuña y su periferia. El artículo 16.1.a dice literalmente «aquellas presentes en el ámbito del Plan», y el Plan NO reparte las especies entre los dos espacios: solo separa los hábitats, en su artículo 17, que la cita como «Pyrrhocorax Pyrrhocorax» (la norma repite el género con mayúscula en el epíteto; el binomio correcto lo lleva en minúscula); EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Chordata', 'Aves', 'Passeriformes', 'Corvidae', 'Pyrrhocorax', 'LC (Preocupación menor)', 'NT — Casi amenazada (Lista Roja española, 2004)', 'LESRPE (RD 139/2011); Directiva Aves 2009/147/CE, Anexo I; Ley 42/2007, Anexo IV', 'Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de Murcia (Ley 7/1995): De interés especial', 'Región de Murcia', NULL, 12065, 2482552, 60, NULL, NULL, NULL
    UNION ALL
    SELECT 'Curruca rabilarga', 'Curruca undata', 'fauna', 'Ave', 'Matorral bajo y denso, jarales, brezales y tomillares', 'Curruca pequeña, oscura y de cola muy larga que suele llevar levantada. El macho tiene el vientre vinoso y el ojo rojo rodeado de un anillo del mismo color. Es muy inquieta y rara vez se deja ver más de unos segundos antes de volver a hundirse en la mata.', NULL, 'Cola larga y erguida, casi vertical al posarse; Ojo y anillo ocular rojos; Vientre de color vinoso, con motitas blancas en la garganta', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Fauvette_pitchou_Ichkeul_NP.jpg?width=1280', 'El Golli Mohamed (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF confirma su presencia con 59 ocurrencias dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Decreto n.º 13/1995, de 31 de marzo, PORN de Sierra Espuña (incluido Barrancos de Gebas), artículos 13, 14 y 16 (BORM n.º 85, de 11 de abril de 1995): la norma la enumera en el ámbito ENTERO del PORN, 19.679 ha, del que el Paisaje Protegido de los Barrancos de Gebas son 1.875 (9,5 %) y el resto el Parque Regional de Sierra Espuña y su periferia. El artículo 16.1.a dice literalmente «aquellas presentes en el ámbito del Plan», y el Plan NO reparte las especies entre los dos espacios: solo separa los hábitats, en su artículo 17, que la cita como «Sylvia undata»; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Chordata', 'Aves', 'Passeriformes', 'Sylviidae', 'Curruca', 'NT — Casi amenazada (Lista Roja mundial de la UICN, 2022)', 'NE — No evaluada (Lista Roja española, 2004)', 'LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial); Directiva Aves 2009/147/CE, Anexo I', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 80931, 2492949, 59, NULL, NULL, NULL
    UNION ALL
    SELECT 'Collalba negra', 'Oenanthe leucura', 'fauna', 'Ave', 'Matorral litoral, laderas secas y roquedos', 'La mayor de las collalbas, enteramente negra salvo el obispillo y la base de la cola, blancos. Vive en cortados y laderas rocosas, donde construye junto al nido una plataforma de piedrecitas que acarrea una a una. Su canto es potente y melodioso.', NULL, 'Cuerpo negro con obispillo blanco muy contrastado; «T» negra invertida en la cola blanca al volar; Montoncitos de piedrecitas junto a la grieta del nido', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Black_Wheatear%2C_Isla_Plana_3.jpg?width=1280', 'Andrew Thomas from Shrewsbury, UK (CC BY-SA 2.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF confirma su presencia con 59 ocurrencias dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Decreto n.º 13/1995, de 31 de marzo, PORN de Sierra Espuña (incluido Barrancos de Gebas), artículos 13, 14 y 16 (BORM n.º 85, de 11 de abril de 1995): la norma la enumera en el ámbito ENTERO del PORN, 19.679 ha, del que el Paisaje Protegido de los Barrancos de Gebas son 1.875 (9,5 %) y el resto el Parque Regional de Sierra Espuña y su periferia. El artículo 16.1.a dice literalmente «aquellas presentes en el ámbito del Plan», y el Plan NO reparte las especies entre los dos espacios: solo separa los hábitats, en su artículo 17; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Passeriformes', 'Muscicapidae', 'Oenanthe', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2018)', 'LC — Preocupación menor (Lista Roja española, 2004)', 'LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial); Directiva Aves 2009/147/CE, Anexo I', 'No incluida en Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia ni en Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de la Región de Murcia ni en Catalogación de la malvasía cabeciblanca (Región de Murcia)', 'Región de Murcia', NULL, 11592, 5231236, 59, NULL, NULL, NULL
    UNION ALL
    SELECT 'Alcaudón común', 'Lanius senator', 'fauna', 'Ave', 'Matorral termomediterráneo semiárido', 'Alcaudón estival de cabeza castaña que caza insectos desde posaderos en el matorral abierto, empalando presas en espinas a modo de despensa.', NULL, 'Capirote castaño rojizo; Caza desde posaderos; Estival de mayo a agosto', 'Primavera y verano (estival)', 'https://commons.wikimedia.org/wiki/Special:FilePath/Lanius_senator01_new.jpg?width=1280', 'Lanius_senator01.jpg: chausinho derivative work: Bogbumper (talk) (CC BY-SA 2.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE (RD 139/2011)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE (RD 139/2011)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF confirma su presencia con 56 ocurrencias dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Decreto n.º 13/1995, de 31 de marzo, PORN de Sierra Espuña (incluido Barrancos de Gebas), artículos 13, 14 y 16 (BORM n.º 85, de 11 de abril de 1995): la norma la enumera en el ámbito ENTERO del PORN, 19.679 ha, del que el Paisaje Protegido de los Barrancos de Gebas son 1.875 (9,5 %) y el resto el Parque Regional de Sierra Espuña y su periferia. El artículo 16.1.a dice literalmente «aquellas presentes en el ámbito del Plan», y el Plan NO reparte las especies entre los dos espacios: solo separa los hábitats, en su artículo 17; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Passeriformes', 'Laniidae', 'Lanius', 'NT — Casi amenazada (Lista Roja mundial de la UICN, 2022)', 'NT — Casi amenazada (Lista Roja española, 2004)', 'LESRPE (RD 139/2011)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 12190, 2492867, 56, NULL, NULL, NULL
    UNION ALL
    SELECT 'Oropéndola', 'Oriolus oriolus', 'fauna', 'Ave', 'Bosques de ribera,hileras de olmos,chopos,sotos,generalmente fluviales,parques,jardines...Mar-1600m', 'Ave de tamaño similar a un mirlo y llamativo color amarillento. El macho exhibe un intenso color amarillo limón en la cabeza — rayada con una línea ocular oscura— y en el cuerpo, que contrasta bastante con las anchas y redondeadas alas, totalmente negras, a excepción de dos parches amarillos a la altura de la articulación de la muñeca. La cola es igualmente amarilla, aunque presenta una ancha banda terminal negra. Posee patas de tono grisáceo y pico rojizo. La hembra, que recuerda a un pequeño pito real, muestra tonos más apagados que el macho, con partes superiores de color verde oliva e inferiores blanquecinas y rayadas en gris. Tiene las alas y la cola pardas, y el pico rojo sucio. Los jóvenes son casi iguales a las hembras, aunque con el pico pardo oscuro y el ojo negruzco. Se trata de un ave esquiva, por lo que la mayoría de las observaciones corresponden a individuos en vuelos breves entre la espesura. Su vuelo, directo y ondulado, alterna aleteos y alas plegadas, de modo similar al del pito real. Su carácter agresivo se evidencia en los frecuentes acosos a otras especies, incluso de mayor tamaño.', NULL, NULL, 'Abril a agosto', 'https://commons.wikimedia.org/wiki/Special:FilePath/Oriole_2.jpg?width=1280', 'autor no indicado (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF confirma su presencia con 54 ocurrencias dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Decreto n.º 13/1995, de 31 de marzo, PORN de Sierra Espuña (incluido Barrancos de Gebas), artículos 13, 14 y 16 (BORM n.º 85, de 11 de abril de 1995): la norma la enumera en el ámbito ENTERO del PORN, 19.679 ha, del que el Paisaje Protegido de los Barrancos de Gebas son 1.875 (9,5 %) y el resto el Parque Regional de Sierra Espuña y su periferia. El artículo 16.1.a dice literalmente «aquellas presentes en el ámbito del Plan», y el Plan NO reparte las especies entre los dos espacios: solo separa los hábitats, en su artículo 17; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Passeriformes', 'Oriolidae', 'Oriolus', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2017)', 'NE — No evaluada (Lista Roja española, 2004)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 11911, 2488949, 54, NULL, NULL, NULL
    UNION ALL
    SELECT 'Lavandera blanca', 'Motacilla alba', 'fauna', 'Ave', NULL, 'Pájaro estilizado de aspecto muy distintivo, con larga cola y tonos blancos, negros y grises. Exhibe dorso gris ceniza, vientre blanco, y alas negras y con bandas blancas cuando están plegadas. Posee cola larga y negra, con plumas externas blancas, y patas y pico negros. El patrón de la cabeza resulta muy contrastado, con la cara blanca rodeada arriba y abajo de negro. Luce un plumaje invernal similar, aunque el color negro en la cabeza está más reducido, y muestra garganta blanca y banda pectoral negra. La lavandera enlutada (M. a. yarrelli), de origen británico, presenta tonos negros en dorso y flancos. Ambos sexos son parecidos, pero la hembra tiene la nuca gris. Los jóvenes resultan más uniformes, sin negro en la cabeza y con banda pectoral grisácea. Un hábito destacado de esta ave es el continuo balanceo de la cola. En invierno se vuelve muy gregaria y se reúne en dormideros.', NULL, NULL, 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/White-Wagtail.jpg?width=1280', 'Andreas Trepte (CC BY-SA 2.5) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF confirma su presencia con 50 ocurrencias dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Decreto n.º 13/1995, de 31 de marzo, PORN de Sierra Espuña (incluido Barrancos de Gebas), artículos 13, 14 y 16 (BORM n.º 85, de 11 de abril de 1995): la norma la enumera en el ámbito ENTERO del PORN, 19.679 ha, del que el Paisaje Protegido de los Barrancos de Gebas son 1.875 (9,5 %) y el resto el Parque Regional de Sierra Espuña y su periferia. El artículo 16.1.a dice literalmente «aquellas presentes en el ámbito del Plan», y el Plan NO reparte las especies entre los dos espacios: solo separa los hábitats, en su artículo 17; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Passeriformes', 'Motacillidae', 'Motacilla', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2019)', 'NE — No evaluada (Lista Roja española, 2004)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 10648, 9687165, 50, NULL, NULL, NULL
    UNION ALL
    SELECT 'Mito', 'Aegithalos caudatus', 'fauna', 'Ave', NULL, 'Es fácil de identificar por la notable longitud de su cola (7-9 centímetros), que contrasta con su pequeño cuerpecillo, de cortas y redondeadas alas. En un primer vistazo resulta un ave con una apariencia general oscura. Sin embargo, observada con atención se aprecia una banda clara que recorre toda la cabeza, así como una pechuga grisácea con tintes rojizos, que contrasta con los tonos negros y grises del dorso, la cola y las alas.', NULL, NULL, 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Long-tailed_Tit_Aegithalos_caudatus.jpg?width=1280', 'Andreas Trepte (CC BY-SA 2.5) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF confirma su presencia con 49 ocurrencias dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Decreto n.º 13/1995, de 31 de marzo, PORN de Sierra Espuña (incluido Barrancos de Gebas), artículos 13, 14 y 16 (BORM n.º 85, de 11 de abril de 1995): la norma la enumera en el ámbito ENTERO del PORN, 19.679 ha, del que el Paisaje Protegido de los Barrancos de Gebas son 1.875 (9,5 %) y el resto el Parque Regional de Sierra Espuña y su periferia. El artículo 16.1.a dice literalmente «aquellas presentes en el ámbito del Plan», y el Plan NO reparte las especies entre los dos espacios: solo separa los hábitats, en su artículo 17, que la cita como «Aeghitalos caudatus» (errata de imprenta del género del mito); EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Passeriformes', 'Aegithalidae', 'Aegithalos', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2016)', 'NE — No evaluada (Lista Roja española, 2004)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 10993, 2495000, 49, NULL, NULL, NULL
    UNION ALL
    SELECT 'Carbonero común', 'Parus major', 'fauna', 'Ave', NULL, 'Se trata de una especie fácilmente reconocible por el color amarillo de su cuerpo, que contrasta con el azul de las alas y la cola. La cabeza es de color negro-azabache y con las mejillas muy blancas, salvo en los jóvenes del año, algo amarillenta. Los machos se distinguen de las hembras por poseer una conspicua banda negra que recorre su cuerpo desde la garganta hasta la base de la cola. Las hembras, en cambio, tienen muy poco marcada dicha banda, que se desdibuja en el vientre.', NULL, NULL, 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/%D0%A1%D0%B8%D0%BD%D0%B8%D1%86%D0%B0_(Parus_major%2C_fem)%2C_%D0%91%D0%B8%D1%82%D1%86%D0%B5%D0%B2%D1%81%D0%BA%D0%B8%D0%B9_%D0%BB%D0%B5%D1%81.jpg?width=1280', 'Dion Art (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF confirma su presencia con 48 ocurrencias dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Decreto n.º 13/1995, de 31 de marzo, PORN de Sierra Espuña (incluido Barrancos de Gebas), artículos 13, 14 y 16 (BORM n.º 85, de 11 de abril de 1995): la norma la enumera en el ámbito ENTERO del PORN, 19.679 ha, del que el Paisaje Protegido de los Barrancos de Gebas son 1.875 (9,5 %) y el resto el Parque Regional de Sierra Espuña y su periferia. El artículo 16.1.a dice literalmente «aquellas presentes en el ámbito del Plan», y el Plan NO reparte las especies entre los dos espacios: solo separa los hábitats, en su artículo 17; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Passeriformes', 'Paridae', 'Parus', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2016)', 'NE — No evaluada (Lista Roja española, 2004)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 11650, 9705453, 48, NULL, NULL, NULL
    UNION ALL
    SELECT 'Colirrojo tizón', 'Phoenicurus ochruros', 'fauna', 'Ave', NULL, 'Ave de pequeño tamaño y diseño peculiar, con obispillo y cola de característico color rojo. El macho presenta el pecho y la cara de color negro azabache, y el resto del cuerpo oscuro, con una mancha blanca en las alas. Las hembras y los jóvenes son pardogrisáceos. Muy terrestre, acostumbra a posarse con figura erguida mientras agita su cola roja. Tiene vuelo amariposado, con batido rápido de alas.', NULL, NULL, 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Hausrotschwanz_Brutpflege_2006-05-21-05.jpg?width=1280', 'Stefan-Xp (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF confirma su presencia con 48 ocurrencias dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Decreto n.º 13/1995, de 31 de marzo, PORN de Sierra Espuña (incluido Barrancos de Gebas), artículos 13, 14 y 16 (BORM n.º 85, de 11 de abril de 1995): la norma la enumera en el ámbito ENTERO del PORN, 19.679 ha, del que el Paisaje Protegido de los Barrancos de Gebas son 1.875 (9,5 %) y el resto el Parque Regional de Sierra Espuña y su periferia. El artículo 16.1.a dice literalmente «aquellas presentes en el ámbito del Plan», y el Plan NO reparte las especies entre los dos espacios: solo separa los hábitats, en su artículo 17; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Passeriformes', 'Muscicapidae', 'Phoenicurus', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2019)', 'NE — No evaluada (Lista Roja española, 2004)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 11886, 5739315, 48, NULL, NULL, NULL
    UNION ALL
    SELECT 'Vencejo común', 'Apus apus', 'fauna', 'Ave', 'Nidos:edificios,acantilados rocosos,cuevas,cajas nido, en colonias.En todo tipo de habitats', 'Presenta silueta en forma de ballesta, cola corta y ahorquillada, y alas estrechas y largas. Posee pico corto, plano y con la boca muy ancha; patas emplumadas y extremadamente cortas, que le impiden posarse en el suelo; y pies pequeños y de fuertes garras, con los cuatro dedos dirigidos hacia delante. Muestra coloración uniforme de tono pardo oscuro, casi negro, excepto en la garganta, que es blanca; la cara inferior de las alas resulta un poco más pálida. En otoño, con su plumaje desgastado, es algo más claro. Ambos sexos son iguales. Los jóvenes se parecen mucho a los adultos, aunque con un tono algo más oscuro y un aspecto escamoso, por los pequeños ribetes blancos que tienen en las plumas. Esta ave es observada casi siempre en vuelo y en grupo. Las condiciones de luz, el fondo y la distancia determinan su apariencia, pudiendo confundirse con frecuencia con el vencejo pálido. Se localiza habitualmente en núcleos urbanos, volando de forma incansable a gran velocidad. Pasa la mayor parte de su vida en el aire, y únicamente se la ve posada cuando entra o sale del nido. Duerme tanto en el nido como en vuelo.', NULL, NULL, 'Abril a agosto', 'https://commons.wikimedia.org/wiki/Special:FilePath/Apus_apus_-Barcelona%2C_Spain-8_(1).jpg?width=1280', 'pau.artigas (CC BY-SA 2.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF confirma su presencia con 46 ocurrencias dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Decreto n.º 13/1995, de 31 de marzo, PORN de Sierra Espuña (incluido Barrancos de Gebas), artículos 13, 14 y 16 (BORM n.º 85, de 11 de abril de 1995): la norma la enumera en el ámbito ENTERO del PORN, 19.679 ha, del que el Paisaje Protegido de los Barrancos de Gebas son 1.875 (9,5 %) y el resto el Parque Regional de Sierra Espuña y su periferia. El artículo 16.1.a dice literalmente «aquellas presentes en el ámbito del Plan», y el Plan NO reparte las especies entre los dos espacios: solo separa los hábitats, en su artículo 17; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Apodiformes', 'Apodidae', 'Apus', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2016)', 'NE — No evaluada (Lista Roja española, 2004)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 10743, 5228676, 46, NULL, NULL, NULL
    UNION ALL
    SELECT 'Abejaruco europeo', 'Merops apiaster', 'fauna', 'Ave', 'Matorral termomediterráneo semiárido', 'Ave colorida y gregaria que caza abejas y libélulas en vuelo sobre espacios abiertos y cría en galerías excavadas en taludes terrosos.', NULL, 'Colorido inconfundible; Reclamo ''prruip'' en vuelo; Cría en taludes de rambla', 'Primavera y verano (estival)', 'https://commons.wikimedia.org/wiki/Special:FilePath/%C5%9Eahl%C3%BBr-33.jpg?width=1280', 'Dûrzan cîrano (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE (RD 139/2011)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE (RD 139/2011)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF confirma su presencia con 45 ocurrencias dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Decreto n.º 13/1995, de 31 de marzo, PORN de Sierra Espuña (incluido Barrancos de Gebas), artículos 13, 14 y 16 (BORM n.º 85, de 11 de abril de 1995): la norma la enumera en el ámbito ENTERO del PORN, 19.679 ha, del que el Paisaje Protegido de los Barrancos de Gebas son 1.875 (9,5 %) y el resto el Parque Regional de Sierra Espuña y su periferia. El artículo 16.1.a dice literalmente «aquellas presentes en el ámbito del Plan», y el Plan NO reparte las especies entre los dos espacios: solo separa los hábitats, en su artículo 17; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Coraciiformes', 'Meropidae', 'Merops', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2019)', 'NE — No evaluada (Lista Roja española, 2004)', 'LESRPE (RD 139/2011)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 10738, 2475443, 45, NULL, NULL, NULL
