    SELECT 'Halcón peregrino', 'Falco peregrinus', 'fauna', 'Ave rapaz', 'Cortados y áreas abiertas', 'Halcón robusto de alas puntiagudas y cola corta, capaz de superar los 300 km/h en el picado con que abate a otras aves en pleno vuelo. Se reconoce por la ancha bigotera negra que baja desde el ojo sobre un pecho claro y barrado.', NULL, 'Bigotera negra ancha bajo el ojo, como un casco; Silueta de ancla: alas puntiagudas y cola corta; Pecho claro con barrado fino en horizontal', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Falco_peregrinus_-_01.jpg?width=1280', 'Carlos Delgado (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial (Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Murcia.)","ambito":"autonómico","origen":"regionalStatus del park.json"}', 0, 1, NULL, 'GBIF confirma su presencia con 6 ocurrencias dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Decreto n.º 13/1995, de 31 de marzo, PORN de Sierra Espuña (incluido Barrancos de Gebas), artículos 13, 14 y 16 (BORM n.º 85, de 11 de abril de 1995): la norma la enumera en el ámbito ENTERO del PORN, 19.679 ha, del que el Paisaje Protegido de los Barrancos de Gebas son 1.875 (9,5 %) y el resto el Parque Regional de Sierra Espuña y su periferia. El artículo 16.1.a dice literalmente «aquellas presentes en el ámbito del Plan», y el Plan NO reparte las especies entre los dos espacios: solo separa los hábitats, en su artículo 17; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Falconiformes', 'Falconidae', 'Falco', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2021)', 'EN — En peligro (Lista Roja española, 2004)', 'LESRPE; Directiva Aves 2009/147/CE, Anexo I; Reglamento CITES (CE) 338/97, Anexo A', 'Especies de interés especial (Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Murcia.)', 'Región de Murcia', NULL, 11963, 2481047, 6, NULL, NULL, NULL
    UNION ALL
    SELECT 'Avión roquero', 'Ptyonoprogne rupestris', 'fauna', 'Ave', 'Acantilados mediterráneos con Limonium', 'Hirundínido pardo y robusto que vuela pegado a las paredes rocosas de acantilados y barrancos, donde construye su nido de barro.', NULL, 'Vuelo pegado a las paredes; Manchas claras en la cola; Nido de barro en cortados', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Ptyonoprogne_rupestris_in_flight.jpg?width=1280', 'ferran pestaña (CC BY-SA 2.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE (RD 139/2011)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE (RD 139/2011)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF confirma su presencia con 6 ocurrencias dentro del espacio (barrido de 2026-08-22); las aves no se adscriben a hábitats; Decreto n.º 13/1995, de 31 de marzo, PORN de Sierra Espuña (incluido Barrancos de Gebas), artículos 13, 14 y 16 (BORM n.º 85, de 11 de abril de 1995): la norma la enumera en el ámbito ENTERO del PORN, 19.679 ha, del que el Paisaje Protegido de los Barrancos de Gebas son 1.875 (9,5 %) y el resto el Parque Regional de Sierra Espuña y su periferia. El artículo 16.1.a dice literalmente «aquellas presentes en el ámbito del Plan», y el Plan NO reparte las especies entre los dos espacios: solo separa los hábitats, en su artículo 17; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Passeriformes', 'Hirundinidae', 'Ptyonoprogne', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2017)', 'NE — No evaluada (Lista Roja española, 2004)', 'LESRPE (RD 139/2011)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 12131, 4408796, 6, NULL, NULL, NULL
