-- ------------------------------------------------------------------------------------------------
-- 4. Vínculos especie↔hábitat (30). `evidence` = lo que declara el `source` de cada ficha; ver cabecera.
-- ------------------------------------------------------------------------------------------------
INSERT INTO species_habitats (species_id, habitat_id, evidence)
SELECT sp.id, hb.id, v.evidence
FROM parks pk
JOIN (
    SELECT 'Lycium intricatum' scientific_name, 'matorrales-termomediterraneos-y-5330' habitat_slug, 'observada_gbif' evidence
    UNION ALL
    SELECT 'Lycium intricatum', 'zonas-subestepicas-de-6220', 'observada_gbif'
    UNION ALL
    SELECT 'Tarentola mauritanica', 'matorrales-termomediterraneos-y-5330', 'observada_gbif'
    UNION ALL
    SELECT 'Tarentola mauritanica', 'zonas-subestepicas-de-6220', 'observada_gbif'
    UNION ALL
    SELECT 'Hemorrhois hippocrepis', 'matorrales-termomediterraneos-y-5330', 'observada_gbif'
    UNION ALL
    SELECT 'Hemorrhois hippocrepis', 'zonas-subestepicas-de-6220', 'observada_gbif'
    UNION ALL
    SELECT 'Pinus halepensis', 'matorrales-termomediterraneos-y-5330', 'caracteristica'
    UNION ALL
    SELECT 'Pinus halepensis', 'zonas-subestepicas-de-6220', 'observada_gbif'
    UNION ALL
    SELECT 'Cynomorium coccineum', 'matorrales-termomediterraneos-y-5330', 'observada_gbif'
    UNION ALL
    SELECT 'Cynomorium coccineum', 'zonas-subestepicas-de-6220', 'observada_gbif'
    UNION ALL
    SELECT 'Hemidactylus turcicus', 'matorrales-termomediterraneos-y-5330', 'observada_gbif'
    UNION ALL
    SELECT 'Hemidactylus turcicus', 'zonas-subestepicas-de-6220', 'observada_gbif'
    UNION ALL
    SELECT 'Hyparrhenia hirta', 'matorrales-termomediterraneos-y-5330', 'observada_gbif'
    UNION ALL
    SELECT 'Hyparrhenia hirta', 'zonas-subestepicas-de-6220', 'caracteristica'
    UNION ALL
    SELECT 'Limonium insigne', 'matorrales-termomediterraneos-y-5330', 'observada_gbif'
    UNION ALL
    SELECT 'Limonium insigne', 'zonas-subestepicas-de-6220', 'observada_gbif'
    UNION ALL
    SELECT 'Lygeum spartum', 'matorrales-termomediterraneos-y-5330', 'observada_gbif'
    UNION ALL
    SELECT 'Lygeum spartum', 'zonas-subestepicas-de-6220', 'caracteristica'
    UNION ALL
    SELECT 'Malpolon monspessulanus', 'matorrales-termomediterraneos-y-5330', 'observada_gbif'
    UNION ALL
    SELECT 'Malpolon monspessulanus', 'zonas-subestepicas-de-6220', 'observada_gbif'
    UNION ALL
    SELECT 'Mauremys leprosa', 'matorrales-termomediterraneos-y-5330', 'observada_gbif'
    UNION ALL
    SELECT 'Mauremys leprosa', 'zonas-subestepicas-de-6220', 'observada_gbif'
    UNION ALL
    SELECT 'Ononis ornithopodioides', 'matorrales-termomediterraneos-y-5330', 'observada_gbif'
    UNION ALL
    SELECT 'Ononis ornithopodioides', 'zonas-subestepicas-de-6220', 'caracteristica'
    UNION ALL
    SELECT 'Pistacia lentiscus', 'matorrales-termomediterraneos-y-5330', 'observada_gbif'
    UNION ALL
    SELECT 'Pistacia lentiscus', 'zonas-subestepicas-de-6220', 'observada_gbif'
    UNION ALL
    SELECT 'Psammodromus algirus', 'matorrales-termomediterraneos-y-5330', 'observada_gbif'
    UNION ALL
    SELECT 'Psammodromus algirus', 'zonas-subestepicas-de-6220', 'observada_gbif'
    UNION ALL
    SELECT 'Rhamnus lycioides', 'matorrales-termomediterraneos-y-5330', 'observada_gbif'
    UNION ALL
    SELECT 'Rhamnus lycioides', 'zonas-subestepicas-de-6220', 'observada_gbif'
) v
JOIN species sp ON sp.park_id = pk.id AND sp.scientific_name = v.scientific_name
JOIN habitats hb ON hb.park_id = pk.id AND hb.slug = v.habitat_slug
WHERE pk.slug = 'barrancos-de-gebas'
ON DUPLICATE KEY UPDATE evidence = VALUES(evidence);

-- ------------------------------------------------------------------------------------------------
-- 5. Comprobación posterior. Debe devolver exactamente los recuentos de la cabecera.
-- ------------------------------------------------------------------------------------------------
SELECT
    (SELECT COUNT(*) FROM parks WHERE slug = 'barrancos-de-gebas') AS espacio,
    (SELECT COUNT(*) FROM habitats h JOIN parks p ON p.id = h.park_id WHERE p.slug = 'barrancos-de-gebas') AS habitats,
    (SELECT COUNT(*) FROM species s JOIN parks p ON p.id = s.park_id WHERE p.slug = 'barrancos-de-gebas') AS especies,
    (SELECT COUNT(*) FROM species_habitats sh JOIN species s ON s.id = sh.species_id JOIN parks p ON p.id = s.park_id WHERE p.slug = 'barrancos-de-gebas') AS vinculos;
